using UnityEngine;

/// Las 88 constelaciones oficiales y las palabras escondidas del cielo.
///
/// DATOS
///
/// Figuras y estrellas reales: trazado de las constelaciones del proyecto d3-celestial
/// (Olaf Frohn, licencia BSD-3, github.com/ofrohn/d3-celestial), con la magnitud y el color
/// (índice B-V) de cada estrella sacados de su catálogo. Ya vienen proyectadas al plano
/// (proyección gnómica desde el centro de cada figura, con el este a la izquierda, como se
/// ven en el cielo) y normalizadas: el lado más largo mide 1. La Serpiente va en dos figuras,
/// cabeza y cola, porque Ofiuco la parte en dos.
///
/// Por estrella, 6 números: x, y, magnitud (más baja = más brillante), r, g, b.
public static class SkyCatalog
{
    public class Figure
    {
        public readonly string name;
        /// Tamaño real en el cielo, en grados. Las grandes se dibujan más grandes
        public readonly float extentDeg;
        public readonly float[] stars;
        public readonly int[] lines;   // pares de índices de estrella
        public int StarCount => stars.Length / 6;
        public Figure(string name, float extentDeg, float[] stars, int[] lines)
        { this.name = name; this.extentDeg = extentDeg; this.stars = stars; this.lines = lines; }
    }

